<script setup lang="ts">
import { computed, nextTick, ref, watch } from 'vue'
import { Clock3, Gauge, HardDrive, Zap, Activity } from 'lucide-vue-next'
import { ACTIVITY_DAY, activityAnnualCells, activityCellIndex, activityLifetime, activityTopics, workCalendar, workIntervals, workSummary, storage, storageTotal } from './activityStoryData'
import { compactToken } from '../../components/donvisDemoData'
const props = withDefaults(defineProps<{ initialTab?: 'work' | 'effort' | 'storage' | 'lifetime' }>(), { initialTab: 'work' })
const topic = ref<string>(props.initialTab), days = ref(7), scope = ref('主会话'), selectedStorage = ref('工作树')
watch(() => props.initialTab, value => chooseTopic(value))
const current = computed(() => activityTopics.find(item => item.id === topic.value)!)
const work = computed(() => workSummary(days.value))
const activeStorage = computed(() => storage.find(item => item.name === selectedStorage.value)!)
const cells = activityAnnualCells
const lifetime = activityLifetime(cells)
const calendar = computed(() => workCalendar(days.value))
const selectedWorkDate = ref(ACTIVITY_DAY)
const selectedWork = computed(() => calendar.value.find(day => day.at === selectedWorkDate.value) ?? calendar.value[calendar.value.length - 1]!)
const selectedCell = ref(cells.findIndex(cell => cell.at === ACTIVITY_DAY))
const annualSample = computed(() => cells[selectedCell.value]!)
const calendarScroll = ref<HTMLElement>()
const lifetimeMetrics = [
  { title: '累计 Token', ...compactToken(lifetime.total) }, { title: '单日峰值', ...compactToken(lifetime.peak) },
  { title: '最长任务', value: '42', unit: '分' }, { title: '最长连续', value: String(lifetime.longest), unit: '天' }, { title: '当前连续', value: String(lifetime.current), unit: '天' },
]
function revealCell(focus = false) {
  const pane = calendarScroll.value, cell = pane?.querySelector<HTMLButtonElement>(`[data-day="${selectedCell.value}"]`)
  if (!pane || !cell) return
  pane.scrollLeft = cell.offsetLeft - (pane.clientWidth - cell.offsetWidth) / 2
  if (focus) cell.focus({ preventScroll: true })
}
function chooseTopic(id: string) { topic.value = id; if (id === 'lifetime') nextTick(() => revealCell()) }
function calendarKey(event: KeyboardEvent, index: number) {
  if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown', 'Home', 'End'].includes(event.key)) return
  event.preventDefault(); selectedCell.value = activityCellIndex(index, event.key)
  nextTick(() => revealCell(true))
}
const efforts = computed(() => scope.value === '主会话' ? [{ label: 'HIGH', value: 48, color: '#2563eb' }, { label: 'ULTRA', value: 32, color: '#8050d3' }, { label: 'MEDIUM', value: 20, color: '#0086a8' }] : [{ label: 'HIGH', value: 24, color: '#2563eb' }, { label: 'ULTRA', value: 16, color: '#8050d3' }, { label: 'MEDIUM', value: 60, color: '#0086a8' }])
function gradient(items: { value: number; color: string }[]) { let start = 0; return `conic-gradient(${items.map(item => { const end = start + item.value; const stop = `${item.color} ${start}% ${end}%`; start = end; return stop }).join(',')})` }
</script>

<template>
  <section id="activity" class="activity-story" aria-labelledby="activity-title">
    <nav class="activity-tabs" aria-label="运行与复盘功能"><button v-for="item in activityTopics" :key="item.id" type="button" :aria-pressed="topic === item.id" @click="chooseTopic(item.id)">{{ item.title }}</button></nav>
    <div class="activity-layout">
      <div class="activity-copy"><h2 id="activity-title">{{ current.lead }}</h2><p>{{ current.text }}</p><span>{{ current.caption }}</span><a href="#features">查看全部功能 ↗</a></div>
      <div class="activity-stage">
        <div class="activity-native" aria-label="依据 Donvis 当前原生界面重绘，示例数据">
          <template v-if="topic === 'work'">
            <header><h3><Clock3 :size="16" />工作与空闲</h3><small>自然日利用率</small></header>
            <div class="activity-segments" role="group" aria-label="工作时间范围"><button v-for="range in [1,7,30]" :key="range" type="button" :aria-pressed="days === range" @click="days = range">{{ range === 1 ? '今天' : `${range} 天` }}</button></div>
            <h4>Codex</h4><div class="activity-metrics"><div><span>工作时间占比</span><strong style="color:#8050d3">{{ work.percent }}<small>%</small></strong></div><div><span>工作</span><strong style="color:#009588">{{ work.hours.toFixed(1) }}<small>小时</small></strong></div><div><span>空闲</span><strong style="color:#2563eb">{{ work.idle.toFixed(1) }}<small>小时</small></strong></div></div>
            <div v-if="days === 1" class="work-timeline"><div class="work-line"><i v-for="item in workIntervals" :key="item.start" :style="{ left: `${item.start / 14 * 100}%`, width: `${(item.end - item.start) / 14 * 100}%` }" :title="`${item.start}–${item.end} 时工作`"></i></div><div class="work-axis"><span>00:00</span><span>07:00</span><span>14:00</span></div><p>绿色为已记录的工作时段</p></div>
            <template v-else><div class="work-calendar" :class="{ 'is-month': days === 30 }" role="group" aria-label="每天工作时间"><button v-for="day in calendar" :key="day.at" type="button" :aria-label="`${day.fullDate}，工作 ${day.hours} 小时`" :aria-pressed="selectedWork.at === day.at" @click="selectedWorkDate = day.at" @focus="selectedWorkDate = day.at"><span>{{ day.label }}</span><i :style="{ transform: `scaleY(${day.hours / 7})` }"></i><small>{{ day.hours }}h</small></button></div><p class="work-selection" aria-live="polite">{{ selectedWork.fullDate }} <strong>工作 {{ selectedWork.hours }} 小时</strong></p></template>
            <footer>工作时段来自任务开始与结束记录；此处为展示样本。</footer>
          </template>
          <template v-else-if="topic === 'effort'">
            <div class="activity-segments" role="group" aria-label="推理统计范围"><button v-for="item in ['主会话','子 Agent']" :key="item" type="button" :aria-pressed="scope === item" @click="scope = item">{{ item }}</button></div>
            <div class="effort-grid"><article><h3><Gauge :size="15" />推理强度</h3><div class="effort-ring" :style="{ background: gradient(efforts) }"><span>{{ scope }}</span></div><div class="effort-legend"><span v-for="item in efforts" :key="item.label"><i :style="{ background: item.color }"></i>{{ item.label }}<b>{{ item.value }}%</b></span></div></article><article><h3><Zap :size="15" />更快用量</h3><div class="effort-ring" :style="{ background: `conic-gradient(#c07305 0 ${scope === '主会话' ? 28 : 40}%,#2563eb 0)` }"><span>已结束任务</span></div><div class="effort-legend"><span><i style="background:#c07305"></i>开启<b>{{ scope === '主会话' ? 28 : 40 }}%</b></span><span><i style="background:#2563eb"></i>标准<b>{{ scope === '主会话' ? 72 : 60 }}%</b></span></div></article></div>
            <footer>已结束任务的时长占比 · 并行任务分别累计</footer>
          </template>
          <template v-else-if="topic === 'storage'">
            <header><h3><HardDrive :size="16" />Codex 已占用空间</h3><small>占用构成</small></header>
            <div class="storage-total">{{ (storageTotal / 1000).toFixed(2) }}<small>GB 已占用</small></div>
            <div class="storage-strip" aria-label="磁盘占用构成"><button v-for="item in storage" :key="item.name" type="button" :aria-label="`${item.name} ${item.size} MB`" :style="{ flex: item.size, background: item.color }" @pointerenter="selectedStorage = item.name" @focus="selectedStorage = item.name" @click="selectedStorage = item.name"></button></div>
            <div class="storage-inspection" aria-live="polite"><span :style="{ color: activeStorage.color }">{{ activeStorage.name }}</span><strong>{{ activeStorage.size }} <small>MB</small></strong><span>{{ (activeStorage.size / storageTotal * 100).toFixed(1) }}%</span></div>
            <div class="storage-legend"><button v-for="item in storage" :key="item.name" type="button" :aria-pressed="selectedStorage === item.name" @click="selectedStorage = item.name"><i :style="{ background: item.color }"></i>{{ item.name }}<b>{{ item.size }} MB</b></button></div><footer>11月6日 14:00 测量 · 示例数据</footer>
          </template>
          <template v-else>
            <header><h3><Activity :size="16" />累计活动</h3><small>已读取的本机记录</small></header>
            <div class="lifetime-metrics"><div v-for="item in lifetimeMetrics" :key="item.title"><span>{{ item.title }}</span><strong>{{ item.value }}<small>{{ item.unit }}</small></strong></div></div>
            <h4>年度用量日历 <small>2026</small></h4><div ref="calendarScroll" class="activity-calendar-scroll"><div class="activity-heatmap" role="group" aria-label="2026 年度 Token 用量日历"><button v-for="cell in cells" :key="cell.index" type="button" :data-day="cell.index" :disabled="cell.future" :tabindex="selectedCell === cell.index ? 0 : -1" :aria-pressed="selectedCell === cell.index" :aria-label="`${cell.fullDate}，${cell.future ? '尚未发生' : `${cell.value.toLocaleString()} Token`}`" :style="{ gridColumn: cell.week + 1, gridRow: cell.weekday + 1, '--day-opacity': cell.value ? .22 + .78 * Math.min(1, cell.value / lifetime.peak) : cell.future ? .035 : .08 }" @click="selectedCell = cell.index" @focus="selectedCell = cell.index" @keydown="calendarKey($event, cell.index)"></button></div></div><div class="annual-inspection" aria-live="polite" aria-atomic="true"><span>{{ annualSample.fullDate }}</span><strong>{{ annualSample.value.toLocaleString() }} <small>Token</small></strong></div><footer>最长任务仅包含有明确开始、完成记录的任务。</footer>
          </template>
        </div>
        <div class="activity-footnote"><span>运行看时段</span><i></i><span>资源看构成</span><i></i><span>复盘看积累</span></div>
      </div>
    </div>
  </section>
</template>

<style scoped>
